using System;using System.Collections.Generic;using System.Globalization;using System.IO;using System.Linq;using System.Reflection;using System.Text;using System.Text.RegularExpressions;
namespace FortsStudio {
 public static partial class Exporter {
  static string Ids(IEnumerable<Block> bs){return "{ "+String.Join(", ",bs.Select(b=>Q(b.Id)))+" }";}
  static string Runtime(Project p){var s=new StringBuilder("dofile('scripts/forts.lua')\nlocal fms_path = path\nlocal fms_folder = "+Q(p.Folder)+"\nlocal fms_default_weapon = "+Q(p.Entities.Where(e=>e.Kind=="weapons").Select(e=>e.Key).FirstOrDefault()??"cannon")+"\nlocal fms_blocks = {\n");foreach(var c in p.Chains.Where(c=>c.Enabled&&c.Event!="native_impact"))foreach(var b in AllBlocks(c.Blocks)){s.Append("["+Q(b.Id)+"] = { kind = "+Q(b.Kind)+", type = "+Q(b.Type)+", value = "+Q(b.Value)+", text = "+Q(b.Text)+", op = "+Q(b.Operator)+", tag = "+Q(b.Tag)+", number = "+N(b.Number)+", interval = "+N(b.Number2)+", children = "+Ids(b.Children)+", otherwise = "+Ids(b.Otherwise));if(b.Type=="sound"||b.Type=="loop_sound"){var clip=p.Sounds.FirstOrDefault(x=>x.Id==b.Value);if(clip!=null)s.Append(", sound = fms_path .. "+Q("/effects/block_"+b.Id+".lua")+", duration = "+N(clip.Duration));}s.Append(" },\n");}s.Append("}\nlocal fms_rules = {\n");foreach(var c in p.Chains.Where(c=>c.Enabled&&c.Event!="native_impact"))s.Append("{ event = "+Q(c.Event)+", source = "+Q(c.Source)+", interval = "+N(c.Interval)+", body = "+Ids(c.Blocks)+" },\n");s.Append("}\nlocal fms_variables = {\n");foreach(var v in p.Variables)s.Append("["+Q(v.Name)+"] = { scope = "+Q(v.Scope)+", initial = "+N(v.Initial)+" },\n");s.Append("}\nlocal fms_entity_audio = {\n");foreach(var e in p.Entities){if(e.WorkAudio.Data.Length>0)s.Append("["+Q(e.Key)+"] = { effect = fms_path .. "+Q("/effects/"+e.Key+"_work.lua")+", duration = "+N(e.WorkAudio.Duration)+", slot = 'work' },\n");if(e.FlightAudio.Data.Length>0)s.Append("["+Q(e.Key)+"] = { effect = fms_path .. "+Q("/effects/"+e.Key+"_flight.lua")+", duration = "+N(e.FlightAudio.Duration)+", slot = 'flight' },\n");}s.Append("}\n");using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("FortsStudio.runtime.lua")){if(stream==null)throw new Exception("Не найден встроенный исполнитель сценариев.");using(var r=new StreamReader(stream))s.Append(r.ReadToEnd());}return s.ToString();}
  static void ValidateExtensions(Project p,List<string> errors){var names=new HashSet<string>();foreach(var v in p.Variables){if(!Regex.IsMatch(v.Name??"",@"^[A-Za-z_]\w{0,39}$")||!names.Add(v.Name))errors.Add("Переменная: неверное или повторное имя "+v.Name);if(v.Scope!="object"&&v.Scope!="global")errors.Add("Неверная область переменной "+v.Name);if(Double.IsNaN(v.Initial)||Double.IsInfinity(v.Initial))errors.Add("Недопустимое начальное значение "+v.Name);}
   foreach(var e in p.Entities){if(e.BuildStages.Count>32)errors.Add(e.NameRu+": максимум 32 этапа.");if(e.BuildStages.Count>0){if(e.Kind!="devices")errors.Add(e.NameRu+": этапы доступны сооружениям.");if(e.BuildStages.Min(x=>x.Progress)!=0)errors.Add(e.NameRu+": первый этап должен начинаться с 0%.");if(e.BuildStages.Select(x=>x.Progress).Distinct().Count()!=e.BuildStages.Count)errors.Add(e.NameRu+": пороги этапов должны различаться.");if(e.BuildStages.Any(x=>x.Progress<0||x.Progress>100))errors.Add(e.NameRu+": прогресс этапа должен быть 0–100%. ");}foreach(var clip in new[]{e.DestroyAudio,e.WorkAudio,e.FlightAudio,Primary(e)})CheckClip(clip,e.NameRu,errors);}
   foreach(var clip in p.Sounds){CheckClip(clip,clip.Name,errors);if(!Regex.IsMatch(clip.Id,@"^[A-Za-z0-9_]+$"))errors.Add("Неверный идентификатор звука "+clip.Name);}
   var blockIds=new HashSet<string>();foreach(var c in p.Chains){if(c.Interval<.05||c.Interval>3600)errors.Add(c.Name+": интервал таймера 0,05–3600 секунд.");ValidateBlocks(p,c,c.Blocks,0,blockIds,errors);}
  }
  static void CheckClip(AudioClip c,string name,List<string> errors){if(c.Volume<0||c.Volume>2||Double.IsNaN(c.Volume)||Double.IsInfinity(c.Volume))errors.Add(name+": громкость 0–200%. ");if(c.Data.Length>0&&(c.Duration<.05||c.Duration>3600))errors.Add(name+": длина аудиоцикла 0,05–3600 секунд.");}
  static void ValidateBlocks(Project p,Chain chain,List<Block> bs,int depth,HashSet<string> ids,List<string> errors){if(depth>12){errors.Add(chain.Name+": максимум 12 уровней вложенности.");return;}foreach(var b in bs){if(!Regex.IsMatch(b.Id,@"^[A-Za-z0-9_]+$")||!ids.Add(b.Id))errors.Add(chain.Name+": повторный идентификатор блока.");if(ids.Count>512){errors.Add("В проекте более 512 блоков.");return;}if(Double.IsNaN(b.Number)||Double.IsInfinity(b.Number)||Double.IsNaN(b.Number2)||Double.IsInfinity(b.Number2))errors.Add(chain.Name+": недопустимое число в блоке.");if(chain.Event=="native_impact"&&(b.Children.Count>0||b.Otherwise.Count>0||b.Kind!="condition"&&b.Kind!="action"))errors.Add(chain.Name+": штатные осколки не поддерживают вложенные блоки; используйте обычное событие для циклов.");if((b.Type=="variable"||b.Type=="set_var"||b.Type=="add_var"||b.Type=="multiply_var")&&!p.Variables.Any(v=>v.Name==b.Value))errors.Add(chain.Name+": не объявлена переменная "+b.Value);if((b.Type=="sound"||b.Type=="loop_sound")&&!p.Sounds.Any(a=>a.Id==b.Value&&a.Data.Length>0))errors.Add(chain.Name+": выберите загруженный звук.");if(b.Type=="convert_projectile"||b.Type=="spawn_projectile"){if(!p.Entities.Any(e=>e.Kind=="projectiles"&&e.Key==b.Value)&&!Catalog.Templates.Any(t=>t.Kind=="projectiles"&&t.Key==b.Value))errors.Add(chain.Name+": не найден снаряд "+b.Value);if(b.Type=="convert_projectile"&&chain.Event!="projectile_hit"&&chain.Event!="projectile_spawned"&&chain.Event!="projectile_expired")errors.Add(chain.Name+": преобразование требует события снаряда.");}if(b.Kind=="loop"&&(b.Number2<.05||b.Number2>3600))errors.Add(chain.Name+": интервал цикла 0,05–3600 секунд.");if(b.Kind=="loop"&&b.Type=="repeat"&&b.Text.Length==0&&(b.Number<1||b.Number>10000))errors.Add(chain.Name+": число повторов 1–10000.");if(b.Kind=="delay"&&(b.Number<0||b.Number>3600))errors.Add(chain.Name+": задержка 0–3600 секунд.");if(!new[]{">=","<=","==","~=",">","<"}.Contains(b.Operator))errors.Add(chain.Name+": неверный оператор сравнения.");ValidateBlocks(p,chain,b.Children,depth+1,ids,errors);ValidateBlocks(p,chain,b.Otherwise,depth+1,ids,errors);}}
 }
}
